import{_ as t,a,o as s,a6 as i}from"./chunks/framework.CJDy2q7X.js";const g=JSON.parse('{"title":"Agent Skills","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/build-with-ai/agent-skills.md","filePath":"api/build-with-ai/agent-skills.md","lastUpdated":1787725411000}'),n={name:"api/build-with-ai/agent-skills.md"};function o(l,e,r,h,d,p){return s(),a("div",null,e[0]||(e[0]=[i(`<h1 id="agent-skills" tabindex="-1">Agent Skills <a class="header-anchor" href="#agent-skills" aria-label="Permalink to &quot;Agent Skills&quot;">​</a></h1><p>The <a href="https://github.com/bagisto/agent-skills" target="_blank" rel="noreferrer"><code>bagisto/agent-skills</code></a> repository packages Bagisto&#39;s build-rules as installable <strong>agent skills</strong> — domain-specific instructions that teach an AI agent how to build on and extend the API. This is the fastest way to make an assistant productive on Bagisto: install once, and the agent already knows the flows and the gotchas.</p><h2 id="why-install-them" tabindex="-1">Why install them <a class="header-anchor" href="#why-install-them" aria-label="Permalink to &quot;Why install them&quot;">​</a></h2><p>Without the skills, an agent rediscovers the same lessons every session — often by trial and error against a live store. The skills carry that knowledge up front:</p><ul><li><strong>The correct call sequences.</strong> Catalog → cart → checkout → account are ordered, dependency-aware flows. The skill knows shipping rates need an address first, that a guest cart uses a cart token, and how to merge a guest cart on login.</li><li><strong>The transport gotchas, baked in.</strong> The token model (<code>token</code> is the Bearer, <code>apiToken</code> is legacy), <code>id</code> vs <code>_id</code> vs IRI, the JSON <code>filter:</code> string, <code>sortKey</code>/<code>reverse</code> — the agent applies these instead of guessing.</li><li><strong>Storefront structure.</strong> Which endpoints back the homepage, a category page, a product page, the cart drawer, and the account area — so the generated app matches how the store actually works.</li><li><strong>Docs-first by design.</strong> Each skill routes a task to a reference page that names the endpoints and the flow, then hands off to these docs for the exact request and response. The skill supplies the rules; the pages supply the payloads.</li></ul><p>The result: less back-and-forth, fewer wrong payloads, and generated code that follows the real API contract on the first pass.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><p>The installer is the <a href="https://www.npmjs.com/package/skills" target="_blank" rel="noreferrer"><code>skills</code></a> CLI, which needs <strong>Node 22.20 or newer</strong>. On an older Node the command does not fail gracefully — it aborts with a raw <code>SyntaxError: The requested module &#39;node:util&#39; does not provide an export named &#39;styleText&#39;</code>, which looks like a broken package rather than a version problem. Check with <code>node -v</code> first.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><p><strong>Building an app that consumes the API (storefront / customer app):</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bagisto/agent-skills</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;bagisto-api-shop&quot;</span></span></code></pre></div><p><strong>Building an admin / back-office app:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bagisto/agent-skills</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;bagisto-api-admin&quot;</span></span></code></pre></div><p><strong>Extending the API itself (custom REST/GraphQL endpoints):</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bagisto/agent-skills</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;bagisto-api-develop&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bagisto/agent-skills</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;pest-testing&quot;</span></span></code></pre></div><p><strong>Everything:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bagisto/agent-skills</span></span></code></pre></div><p>Dropping <code>--skill</code> installs <strong>every</strong> skill in the repository, not only the four API ones — the repo also carries theme, package, payment-method, shipping-method, product-type, and Blade skills. Name the skills you want unless you intend to load all of them. <code>npx skills add bagisto/agent-skills --list</code> prints the full set without installing anything.</p><h2 id="running-it-from-inside-an-agent" tabindex="-1">Running it from inside an agent <a class="header-anchor" href="#running-it-from-inside-an-agent" aria-label="Permalink to &quot;Running it from inside an agent&quot;">​</a></h2><p>You can hand these commands to the assistant and let it install its own skills. The CLI detects that it is running inside a coding agent — Claude Code, Codex, Antigravity and others set an environment variable it looks for — and then it skips every prompt and installs to that agent automatically. No extra flags are needed in that case.</p><p>Run the same command yourself in a terminal and it is interactive instead: it asks which agents to install to, and how to link the files. Two flags cover the difference:</p><table tabindex="0"><thead><tr><th>Flag</th><th>Use it when</th></tr></thead><tbody><tr><td><code>-a &lt;agent&gt;</code></td><td>Targeting a specific agent — <code>claude-code</code>, <code>codex</code>, <code>antigravity</code>, <code>cursor</code>, <code>zed</code>, and ~70 more</td></tr><tr><td><code>-y</code></td><td>Scripting the install (CI, a setup script) where nothing can answer a prompt</td></tr></tbody></table><p><code>npx skills add bagisto/agent-skills --skill &quot;bagisto-api-shop&quot; -a claude-code -y</code> is the fully non-interactive form.</p><h2 id="the-skills" tabindex="-1">The skills <a class="header-anchor" href="#the-skills" aria-label="Permalink to &quot;The skills&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Skill</th><th>Use it to</th></tr></thead><tbody><tr><td><code>bagisto-api-shop</code></td><td>Build a storefront / customer app on the Shop API</td></tr><tr><td><code>bagisto-api-admin</code></td><td>Build an admin / back-office app on the Admin API</td></tr><tr><td><code>bagisto-api-develop</code></td><td>Add or extend a REST/GraphQL endpoint in the API package</td></tr><tr><td><code>pest-testing</code></td><td>Write the REST + GraphQL tests that lock both transports</td></tr></tbody></table><p>The three API skills live together under <code>skills/api-platform-development/</code>, and each carries its own <code>reference/</code> tree — the flows, menus, and checklists it routes to. Installing a skill brings its reference pages with it, so a single <code>--skill</code> install is self-contained.</p><h2 id="what-the-skills-do-not-cover-yet" tabindex="-1">What the skills do not cover yet <a class="header-anchor" href="#what-the-skills-do-not-cover-yet" aria-label="Permalink to &quot;What the skills do not cover yet&quot;">​</a></h2><p>The skills are a router over the most-used surfaces, not a mirror of this documentation. Three feature areas are documented here but have no reference page in any skill, on either the shop or the admin side:</p><table tabindex="0"><thead><tr><th>Area</th><th>Documented under</th></tr></thead><tbody><tr><td>Returns / RMA</td><td><a href="/api/workflows/shop/returns-rma.html">Shop</a> and <a href="/api/workflows/admin/returns-rma.html">Admin</a></td></tr><tr><td>EU Withdrawal</td><td><a href="/api/workflows/shop/eu-withdrawal.html">Shop</a> and <a href="/api/workflows/admin/eu-withdrawal.html">Admin</a></td></tr><tr><td>GDPR data requests</td><td><a href="/api/rest-api/shop/gdpr-requests/">Shop</a></td></tr></tbody></table><p>Together with the Settings menus that configure returns — reasons, statuses, rules, and custom fields — that is roughly one page in seven of this documentation. An agent following only the skill&#39;s routing tables will not find them, so when you are building any of those, point it at <a href="/llms.txt"><code>/llms.txt</code></a> and the pages above directly. Everything it needs is documented; the skill just does not signpost it.</p><p>The <code>bagisto-api-develop</code> skill targets Bagisto 2.3.8 and pins an older API Platform dependency set, and it covers extending the API package itself rather than adding endpoints from your own module. For either job on 2.4.x, <a href="/api/for-developers/">For Developers</a> is the current reference — registration wiring, the resource/provider/processor pattern, the naming rules, and the traps. Point the agent there alongside the skill, and treat the skill&#39;s install steps as out of date.</p><h2 id="after-installing" tabindex="-1">After installing <a class="header-anchor" href="#after-installing" aria-label="Permalink to &quot;After installing&quot;">​</a></h2><p>Point the agent at the <a href="/api/build-with-ai/">Build with AI</a> start order — <a href="/api/authentication.html">Authentication</a> and the <a href="/api/workflows/shop/">Storefront</a> overview first, then <a href="/llms.txt"><code>/llms.txt</code></a> to find endpoints, then the <a href="/api/workflows/">Workflows</a> for the call sequence. The skill supplies the rules; the docs supply the exact payloads.</p>`,33)]))}const k=t(n,[["render",o]]);export{g as __pageData,k as default};
